mapper.select:
SELECT IN_TB.* FROM ( SELECT A.SEQ, A.TITLE, A.CONTENT, A.CNT, NVL(A.ATTACH_SEQ,0) ATTACH_SEQ, TO_CHAR(A.REG_DATE,'yyyy-MM-dd') REG_DATE, A.REG_ID, A.BOARD_GBN, ROW_NUMBER() OVER (ORDER BY A.SEQ) AS RNUM, B.EMP_NM, (SELECT COUNT(SEQ) FROM CRM_NOTICE_ANSWER S WHERE S.NOTICE_SEQ = A.SEQ ) NOTICE_CNT, A.SYSTEM_TYPE, ( SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'PROJECT' AND z.p_code = 'PR02' AND z.code = A.SYSTEM_TYPE ) AS system_type_nm, /* 시스템유형 */ A.WORK_TYPE, ( SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'OPERATE' AND z.p_code = A.SYSTEM_TYPE AND z.code = A.WORK_TYPE ) AS work_type_nm, /* 업무유형 */ NVL(C.OPEN_TYPE,'C001') as OPEN_TYPE, ( SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'COMMON' AND z.p_code = 'CD08' AND z.code = NVL(OPEN_TYPE,'C001') ) AS OPEN_TYPE_NM , A.NOTICE_NUM
FROM CRM_BOARD_MGT A INNER JOIN CRM_EMP_MGT B ON A.REG_ID = B.EMP_NO LEFT OUTER JOIN (SELECT NOTICE_SEQ, DECODE(ALL_OPEN_YN,'Y','C001', DECODE(UPPER(MAX(ERP_CODE)),'ERP00','C002','C003')) AS OPEN_TYPE FROM CRM_NOTICE_ACCESS GROUP BY NOTICE_SEQ, ALL_OPEN_YN) C ON A.SEQ = C.NOTICE_SEQ WHERE 1=1
) IN_TB WHERE RNUM BETWEEN #{startRow, jdbcType=INTEGER} AND #{endRow, jdbcType=INTEGER} ORDER BY IN_TB.RNUM DESC

