INSERT INTO CRM_BOARD_MGT 
(
	SEQ, BOARD_GBN, TITLE, CONTENT, CNT, ATTACH_SEQ, REG_DATE, REG_ID
) 
VALUES 
(
	#{seq}, #{board_gbn}, #{title}, #{content}, '0', #{attach_seq}, SYSDATE, #{reg_id}
)


INSERT INTO CRM_NOTICE_ACCESS
(
	SEQ, NOTICE_SEQ, ERP_CODE, ALL_OPEN_YN
) 
VALUES 
(
	MAX_NOTICE_ACCESS_NO.NEXTVAL, #{notice_seq}, #{erp_code}, #{all_open_yn}
)

mapper.update:

UPDATE CRM_BOARD_MGT SET 
	TITLE = #{title}
	,CONTENT = #{content}
	,ATTACH_SEQ = #{attach_seq}
	,UPD_DATE = SYSDATE
	,UPD_ID = #{reg_id}
	,WORK_TYPE = #{work_type}
	,SYSTEM_TYPE = #{system_type} 
WHERE
	SEQ = #{seq}
AND
	BOARD_GBN = #{board_gbn}


UPDATE CRM_BOARD_MGT SET
	CNT = CNT+1
WHERE 
	SEQ = #{seq}
AND
	BOARD_GBN = #{board_gbn}

